Ext._define('judicial.bloke.Window', {
    extend: 'core.RestfulWindow',

    rest: 'judicial.bloke.Restful',

    width: 750,

    blokeTitle: 'Indefinido',

    blokeRestful: 'rh.person.Restful',

    getAddressGrid: function(cfg) {
        if(!this._addressGrid)
            this._addressGrid = Ext._create('rh.endereco.EnderecoGrid', {
                title: 'Endereços',
                height: 350,
                gridAutoLoad: false
            });

        return this._addressGrid;
    },

    person: function(value, dispatch) {
        dispatch = (dispatch === undefined ? true : dispatch);

        if(value !== undefined) {
            this._person = value;

            if(dispatch)
                this.observePerson();
        }

        return this._person;
    },

    observePerson: function() {
        var value = this.person();

        if(value) {
            this.getAddressGrid().enable();
            this.getAddressGrid().setParam('person', value);
            this.getAddressGrid().setFilterProperty('person', value, 100);
        }
        else {
            this.getAddressGrid().disable();
            this.getAddressGrid().setParam('person', value);
            this.getAddressGrid().setFilterProperty('person', value, 100, false);
            this.getAddressGrid().getStore().removeAll();
        }
    },

    getPersonField: function(cfg) {
        if(!this._personField)
            this._personField = Ext._create('core.fields.AutocompleteField', {
                fieldLabel: this.blokeTitle,
                allowBlank: false,
                rest: this.blokeRestful,
                name: "bloke",
                comboListeners: {
                    scope: this,
                    changevalid: function(field, value) {
                        this.person(value);
                    }
                }
            });

        return this._personField;
    },

    getFormPanel: function(cfg) {
        if(!this._formPanel)
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                border: false,
                frame: false,
                items: [
                    {
                        xtype: 'panel',
                        layout: 'form',
                        frame: true,
                        items: [
                            this.getPersonField(cfg)
                        ]
                    },
                    this.getAddressGrid(cfg)
                ]
            });

        return this._formPanel;
    }
});
